  1	//! `src/util/utf8.c`: UTF-8 character lengths, iteration and validation, ported to Rust.
  2	//!
  3	//! libgit2 reads UTF-8 in two strengths, both from utf8proc's class table
  4	//! (`UTF8_CLASS`):
  5	//!
  6	//! - **Structure.** [`char_count`] and [`valid_prefix_len`] split bytes into sequences by their
  7	//!   lead byte's class and its continuation bytes alone, as `utf8_charlen` does: an overlong form,
  8	//!   a surrogate or a code point past U+10FFFF whose bytes are well formed counts as one sequence.
  9	//!   These are not [`str::from_utf8`]'s rules, which reject those.
 10	//! - **Code points.** [`decode_char`] also refuses what `git_utf8_iterate` refuses: overlong forms,
 11	//!   surrogates, code points past U+10FFFF and the noncharacters U+FDD0 to U+FDEF and U+*n*FFFE,
 12	//!   U+*n*FFFF of every plane. What it accepts is therefore always a [`char`].
 13	//!
 14	//! Every function reads its argument alone and holds no state, so the module is native Rust.
 15	//! The C that remains calls the three `git_utf8_*` functions (`src/libgit2/path.c` and
 16	//! `src/libgit2/diff_xdiff.c`, and on Windows `src/util/fs_path.c`), which reach this module
 17	//! through its exports once it has switched; until then the exports compile only under the
 18	//! `ffi-export-src-util-utf8-c` feature.
 19	
 20	use core::error::Error;
 21	use core::fmt;
 22	
 23	/// The length of the UTF-8 sequence each lead byte starts, by its value: 1 for ASCII, 2, 3
 24	/// or 4 for a multi-byte lead (`0xC0` to `0xDF`, `0xE0` to `0xEF`, `0xF0` to `0xF7`), and 0
 25	/// for a byte no sequence starts with, a continuation byte (`0x80` to `0xBF`) or `0xF8` to
 26	/// `0xFF`.
 27	///
 28	/// This is utf8proc's table, which libgit2 copies: its class of `0xC0` and `0xC1`, which
 29	/// start only overlong forms, is 2, and of `0xF5` to `0xF7`, which start only code points past
 30	/// U+10FFFF, is 4, so that [`decode_char`] refuses those by their value, as C does.
 31	///
 32	/// Replaces `glb::utf8proc_utf8class`
 33	#[doc(alias = "utf8proc_utf8class")]
 34	static UTF8_CLASS: [u8; 256] = class_table();
 35	
 36	/// [`UTF8_CLASS`], from the ranges of lead bytes it classifies.
 37	const fn class_table() -> [u8; 256] {
 38	    let mut table = [0; 256];
 39	    let mut byte = 0;
 40	    while byte < table.len() {
 41	        table[byte] = match byte {
 42	            0x00..=0x7F => 1,
 43	            0xC0..=0xDF => 2,
 44	            0xE0..=0xEF => 3,
 45	            0xF0..=0xF7 => 4,
 46	            _ => 0,
 47	        };
 48	        byte += 1;
 49	    }
 50	    table
 51	}
 52	
 53	/// The length of the UTF-8 sequence at the start of `bytes`, by structure alone: its lead
 54	/// byte's class, when `bytes` hold that many bytes and every byte after the lead is a
 55	/// continuation byte (`0b10xx_xxxx`); `None` when `bytes` are empty, the lead starts no
 56	/// sequence or the sequence is cut short or broken.
 57	///
 58	/// `utf8_charlen(str, str_len)` reads past `str_len` when it is 0, from a caller that never
 59	/// passes it: here no length is unbounded, and empty bytes hold none.
 60	///
 61	/// Replaces `fn::utf8_charlen`
 62	#[doc(alias = "utf8_charlen")]
 63	fn sequence_len(bytes: &[u8]) -> Option<usize> {
 64	    let (&lead, rest) = bytes.split_first()?;
 65	    let len = usize::from(UTF8_CLASS[usize::from(lead)]);
 66	    let continuation = rest.get(..len.checked_sub(1)?)?;
 67	    continuation
 68	        .iter()
 69	        .all(|&b| b & 0xC0 == 0x80)
 70	        .then_some(len)
 71	}
 72	
 73	/// The error of [`decode_char`]: the bytes it was given start with no valid code point, or
 74	/// are empty.
 75	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
 76	pub struct InvalidCodePoint;
 77	
 78	impl fmt::Display for InvalidCodePoint {
 79	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 80	        f.write_str("invalid UTF-8 code point")
 81	    }
 82	}
 83	
 84	impl Error for InvalidCodePoint {}
 85	
 86	/// The code point at the start of `bytes`, with the length of its sequence in bytes, which
 87	/// is how far its caller advances to read the next one.
 88	///
 89	/// A sequence is refused, as [`InvalidCodePoint`], when it is broken or cut short, when it
 90	/// is overlong (`C0 80` for U+0000), when it encodes a surrogate (U+D800 to U+DFFF) or a
 91	/// code point past U+10FFFF, and when it encodes a noncharacter: U+FDD0 to U+FDEF, or the
 92	/// last two code points of any plane, U+FFFE and U+FFFF to U+10FFFE and U+10FFFF. Only the
 93	/// bytes of the first sequence are read.
 94	///
 95	/// `git_utf8_iterate(&out, str, 0)` reads `str` as if it were unbounded; empty `bytes`
 96	/// here hold no code point, and are refused.
 97	///
 98	/// ```
 99	/// use libgit2_crustify::libgit2::src::util::utf8::{InvalidCodePoint, decode_char};
100	///
101	/// assert_eq!(decode_char(b"$x"), Ok(('$', 1)));
102	/// assert_eq!(decode_char("¢".as_bytes()), Ok(('¢', 2)));
103	/// assert_eq!(decode_char("𐍈".as_bytes()), Ok(('𐍈', 4)));
104	/// // Overlong, cut short, and a noncharacter.
105	/// assert_eq!(decode_char(b"\xC0\x80"), Err(InvalidCodePoint));
106	/// assert_eq!(decode_char(b"\xE2\x82"), Err(InvalidCodePoint));
107	/// assert_eq!(decode_char("\u{FFFE}".as_bytes()), Err(InvalidCodePoint));
108	/// ```
109	///
110	/// # Errors
111	///
112	/// [`InvalidCodePoint`] when `bytes` start with no valid code point, as above.
113	///
114	/// Replaces `fn::git_utf8_iterate`
115	#[doc(alias = "git_utf8_iterate")]
116	pub fn decode_char(bytes: &[u8]) -> Result<(char, usize), InvalidCodePoint> {
117	    let len = sequence_len(bytes).ok_or(InvalidCodePoint)?;
118	    let tail = |b: u8| u32::from(b & 0x3F);
119	    let code_point = match bytes[..len] {
120	        [a] => Some(u32::from(a)),
121	        [a, b] => Some((u32::from(a & 0x1F) << 6) + tail(b)).filter(|&c| c >= 0x80),
122	        [a, b, c] => Some((u32::from(a & 0x0F) << 12) + (tail(b) << 6) + tail(c))
123	            .filter(|&c| c >= 0x800 && !(0xD800..0xE000).contains(&c))
124	            .filter(|c| !(0xFDD0..0xFDF0).contains(c)),
125	        [a, b, c, d] => {
126	            Some((u32::from(a & 0x07) << 18) + (tail(b) << 12) + (tail(c) << 6) + tail(d))
127	                .filter(|c| (0x1_0000..0x11_0000).contains(c))
128	        }
129	        _ => None,
130	    };
131	    code_point
132	        .filter(|&c| c & 0xFFFF < 0xFFFE)
133	        .and_then(char::from_u32)
134	        .map(|c| (c, len))
135	        .ok_or(InvalidCodePoint)
136	}
137	
138	/// The number of characters in `bytes`: their well-formed sequences, by structure alone, and
139	/// each byte that starts none, which counts as a character of its own.
140	///
141	/// ```
142	/// use libgit2_crustify::libgit2::src::util::utf8::char_count;
143	///
144	/// assert_eq!(char_count(b"$"), 1);
145	/// assert_eq!(char_count("$¢".as_bytes()), 2);
146	/// assert_eq!(char_count("𐍈".as_bytes()), 1);
147	/// // `$`, two bytes that start no sequence, and `4`.
148	/// assert_eq!(char_count(b"\x24\xC0\xC1\x34"), 4);
149	/// ```
150	///
151	/// Replaces `fn::git_utf8_char_length`
152	#[doc(alias = "git_utf8_char_length")]
153	#[must_use]
154	pub fn char_count(bytes: &[u8]) -> usize {
155	    let mut rest = bytes;
156	    let mut count = 0;
157	    while !rest.is_empty() {
158	        let len = sequence_len(rest).unwrap_or(1);
159	        rest = &rest[len..];
160	        count += 1;
161	    }
162	    count
163	}
164	
165	/// The length in bytes of the longest prefix of `bytes` made of well-formed sequences, by
166	/// structure alone: the offset of the first byte that starts no sequence, or of the first
167	/// sequence broken or cut short, or `bytes.len()`.
168	///
169	/// ```
170	/// use libgit2_crustify::libgit2::src::util::utf8::valid_prefix_len;
171	///
172	/// assert_eq!(valid_prefix_len("$¢".as_bytes()), 3);
173	/// assert_eq!(valid_prefix_len(b"ab\xFFcd"), 2);
174	/// // A sequence cut short by the end of the bytes.
175	/// assert_eq!(valid_prefix_len(b"ab\xE2\x82"), 2);
176	/// ```
177	///
178	/// Replaces `fn::git_utf8_valid_buf_length`
179	#[doc(alias = "git_utf8_valid_buf_length")]
180	#[must_use]
181	pub fn valid_prefix_len(bytes: &[u8]) -> usize {
182	    let mut offset = 0;
183	    while let Some(len) = sequence_len(&bytes[offset..]) {
184	        offset += len;
185	    }
186	    offset
187	}
188	
189	/// The gateway through which the C that remains calls this module once it has switched:
190	/// `git_utf8_iterate`, `git_utf8_char_length` and `git_utf8_valid_buf_length`, each
191	/// checked against its raw binding's signature, so that a C declaration that drifts fails
192	/// to build.
193	#[cfg(feature = "ffi-export-src-util-utf8-c")]
194	mod ffi_export {
195	    use core::ffi::{c_char, c_int};
196	    use core::slice;
197	
198	    use ffibox::callback::barrier;
199	
200	    use super::{char_count, decode_char, valid_prefix_len};
201	    use crate::sys::libgit2 as sys;
202	
203	    // Each export has its raw binding's type: the array's elements coerce to one function
204	    // pointer type only when their signatures agree.
205	    const _: () = {
206	        let _ = [sys::git_utf8_iterate, git_utf8_iterate];
207	        let _ = [sys::git_utf8_char_length, git_utf8_char_length];
208	        let _ = [sys::git_utf8_valid_buf_length, git_utf8_valid_buf_length];
209	    };
210	
211	    /// The `str_len` bytes at `str`, as C passes a string and its size; no bytes when
212	    /// `str_len` is 0, whatever `str` is, NULL included.
213	    ///
214	    /// # Safety
215	    ///
216	    /// When `str_len` is not 0, `str` is valid for reads of `str_len` bytes, which nothing
217	    /// writes while the returned slice lives.
218	    unsafe fn bytes<'a>(str: *const c_char, str_len: usize) -> &'a [u8] {
219	        if str_len == 0 {
220	            return &[];
221	        }
222	        // SAFETY: `str_len` is not 0, so the caller guarantees that `str` is valid for reads
223	        // of `str_len` bytes nothing writes while the slice lives, which is the call that
224	        // receives it; `u8` and `c_char` have one size and alignment.
225	        unsafe { slice::from_raw_parts(str.cast::<u8>(), str_len) }
226	    }
227	
228	    /// `git_utf8_iterate`: [`decode_char`] of the `str_len` bytes at `str`, its code point
229	    /// written through `out` and its length returned; on a refusal, 0 is written and -1
230	    /// returned, as C does. A panic is reported as a refusal.
231	    ///
232	    /// With `str_len` 0, C reads `str` as if it were unbounded; here it holds no code point,
233	    /// and the call is refused without reading `str`.
234	    ///
235	    /// # Safety
236	    ///
237	    /// `out` is valid for a write of a `u32`, and `str` for reads of `str_len` bytes.
238	    #[unsafe(no_mangle)]
239	    unsafe extern "C" fn git_utf8_iterate(
240	        out: *mut u32,
241	        str: *const c_char,
242	        str_len: usize,
243	    ) -> c_int {
244	        // SAFETY: the caller guarantees that `str` is valid for reads of `str_len` bytes,
245	        // which C does not change during the call.
246	        let bytes = unsafe { bytes(str, str_len) };
247	        let (code_point, len) = barrier(
248	            || match decode_char(bytes) {
249	                Ok((c, len)) => (u32::from(c), c_int::try_from(len).unwrap_or(-1)),
250	                Err(_) => (0, -1),
251	            },
252	            || (0, -1),
253	        );
254	        // SAFETY: the caller guarantees that `out` is valid for a write of a `u32`.
255	        unsafe { out.write(code_point) };
256	        len
257	    }
258	
259	    /// `git_utf8_char_length`: [`char_count`] of the `str_len` bytes at `str`. It cannot
260	    /// fail, so a panic aborts.
261	    ///
262	    /// # Safety
263	    ///
264	    /// `str` is valid for reads of `str_len` bytes.
265	    #[unsafe(no_mangle)]
266	    unsafe extern "C" fn git_utf8_char_length(str: *const c_char, str_len: usize) -> usize {
267	        // SAFETY: the caller guarantees that `str` is valid for reads of `str_len` bytes,
268	        // which C does not change during the call.
269	        let bytes = unsafe { bytes(str, str_len) };
270	        barrier(|| char_count(bytes), || std::process::abort())
271	    }
272	
273	    /// `git_utf8_valid_buf_length`: [`valid_prefix_len`] of the `str_len` bytes at `str`. It
274	    /// cannot fail, so a panic aborts.
275	    ///
276	    /// # Safety
277	    ///
278	    /// `str` is valid for reads of `str_len` bytes.
279	    #[unsafe(no_mangle)]
280	    unsafe extern "C" fn git_utf8_valid_buf_length(str: *const c_char, str_len: usize) -> usize {
281	        // SAFETY: the caller guarantees that `str` is valid for reads of `str_len` bytes,
282	        // which C does not change during the call.
283	        let bytes = unsafe { bytes(str, str_len) };
284	        barrier(|| valid_prefix_len(bytes), || std::process::abort())
285	    }
286	}
