  1	//! Equivalence of `src/util/utf8.c`'s exported functions with their ports: `git_utf8_iterate`
  2	//! with `decode_char`, `git_utf8_char_length` with `char_count` and
  3	//! `git_utf8_valid_buf_length` with `valid_prefix_len`, each C call reading its own copy of
  4	//! the bytes the Rust reads.
  5	//!
  6	//! `decode_char`'s result is compared through the mapping its safe API applies to C's: a code
  7	//! point and its length are what `git_utf8_iterate` writes through `out` and returns, and a
  8	//! refusal is its -1 with 0 written. Empty bytes are not compared: `git_utf8_iterate` reads
  9	//! past a size of 0, where `decode_char` refuses them, a unit test's case.
 10	//!
 11	//! The static `utf8_charlen` and `utf8proc_utf8class` are compared through the three: every
 12	//! lead byte, followed by every kind of byte after it, reaches each class of the table and
 13	//! each of `utf8_charlen`'s outcomes.
 14	
 15	use std::ffi::c_int;
 16	
 17	use libgit2_crustify::libgit2::src::util::utf8::{char_count, decode_char, valid_prefix_len};
 18	use libgit2_crustify::sys::libgit2 as sys;
 19	
 20	/// `git_utf8_iterate` of a copy of `bytes`, which are not empty: what it writes through `out`
 21	/// and what it returns.
 22	fn c_iterate(bytes: &[u8]) -> (u32, c_int) {
 23	    assert!(!bytes.is_empty(), "git_utf8_iterate reads past a size of 0");
 24	    let copy = bytes.to_vec();
 25	    let mut out = u32::MAX;
 26	    // SAFETY: `copy` holds `copy.len()` bytes, which the call reads only within that size
 27	    // when it is not 0, and `out` is a live `u32` it writes.
 28	    let len = unsafe { sys::git_utf8_iterate(&raw mut out, copy.as_ptr().cast(), copy.len()) };
 29	    (out, len)
 30	}
 31	
 32	/// `decode_char` of `bytes`, as `git_utf8_iterate` reports it.
 33	fn rust_iterate(bytes: &[u8]) -> (u32, c_int) {
 34	    decode_char(bytes).map_or((0, -1), |(c, len)| {
 35	        (u32::from(c), c_int::try_from(len).expect("at most 4"))
 36	    })
 37	}
 38	
 39	/// `git_utf8_char_length` of a copy of `bytes`.
 40	fn c_char_length(bytes: &[u8]) -> usize {
 41	    let copy = bytes.to_vec();
 42	    // SAFETY: `copy` holds `copy.len()` bytes, which the call reads only within that size.
 43	    unsafe { sys::git_utf8_char_length(copy.as_ptr().cast(), copy.len()) }
 44	}
 45	
 46	/// `git_utf8_valid_buf_length` of a copy of `bytes`.
 47	fn c_valid_buf_length(bytes: &[u8]) -> usize {
 48	    let copy = bytes.to_vec();
 49	    // SAFETY: `copy` holds `copy.len()` bytes, which the call reads only within that size.
 50	    unsafe { sys::git_utf8_valid_buf_length(copy.as_ptr().cast(), copy.len()) }
 51	}
 52	
 53	/// The three functions on `bytes`, C's and Rust's alike.
 54	fn assert_same(bytes: &[u8]) {
 55	    if !bytes.is_empty() {
 56	        assert_eq!(
 57	            rust_iterate(bytes),
 58	            c_iterate(bytes),
 59	            "iterate {bytes:02X?}"
 60	        );
 61	    }
 62	    assert_eq!(
 63	        char_count(bytes),
 64	        c_char_length(bytes),
 65	        "char_length {bytes:02X?}"
 66	    );
 67	    assert_eq!(
 68	        valid_prefix_len(bytes),
 69	        c_valid_buf_length(bytes),
 70	        "valid_buf_length {bytes:02X?}"
 71	    );
 72	}
