  2	//! `git_utf8_iterate`, `git_utf8_char_length` and `git_utf8_valid_buf_length`, checked
  3	//! against their contracts.
  4	//!
  5	//! `char_count_carries_over_the_c_test` carries over the module's one C test
  6	//! case, `test_utf8__char_length` (`tests/util/utf8.c`); the others cover the boundaries of
  7	//! each sequence length and what `decode_char` refuses. None reaches C, so Miri runs them all.
  8	
  9	use libgit2_crustify::libgit2::src::util::utf8::{
 10	    InvalidCodePoint, char_count, decode_char, valid_prefix_len,
 11	};
 12	
 13	/// Carries over `test_utf8__char_length`: its inputs and counts, unchanged.
 14	#[test]
 15	fn char_count_carries_over_the_c_test() {
 16	    assert_eq!(char_count(b""), 0);
 17	    assert_eq!(char_count(b"$"), 1);
 18	    assert_eq!(char_count(b"abcde"), 5);
 19	    assert_eq!(char_count(b"\xc2\xa2"), 1);
 20	    assert_eq!(char_count(b"\x24\xc2\xa2"), 2);
 21	    assert_eq!(char_count(b"\xf0\x90\x8d\x88"), 1);
 22	
 23	    // uncontinued character counted as single characters
 24	    assert_eq!(char_count(b"\x24\xc2"), 2);
 25	    assert_eq!(char_count(b"\x24\xc2\xc2\xa2"), 3);
 26	
 27	    // invalid characters are counted as single characters
 28	    assert_eq!(char_count(b"\x24\xc0\xc0\x34"), 4);
 29	    assert_eq!(char_count(b"\x24\xf5\xfd\xc2"), 4);
 30	}
 31	
 32	/// A sequence is split by structure alone: an overlong form, a surrogate and a code point
 33	/// past U+10FFFF, well formed, are one character each; a sequence cut short or broken counts
 34	/// its lead alone, and its continuation bytes, which start none, one each.
 35	#[test]
 36	fn char_count_splits_by_structure() {
 37	    assert_eq!(char_count(b"\xC0\x80"), 1);
 38	    assert_eq!(char_count(b"\xED\xA0\x80"), 1);
 39	    assert_eq!(char_count(b"\xF4\x90\x80\x80"), 1);
 40	    assert_eq!(char_count(b"\xF0\x90\x8D"), 3);
 41	    assert_eq!(char_count(b"\xF0\x41\x8D\x88"), 4);
 42	    assert_eq!(char_count(&[0x80; 5]), 5);
 43	    assert_eq!(char_count(&[0xFF; 3]), 3);
 44	    assert_eq!(char_count("aé€𐍈".as_bytes()), 4);
 45	}
 46	
 47	/// Every valid string counts as many characters as the standard library's `chars`.
 48	#[test]
 49	fn char_count_matches_chars_on_valid_strings() {
 50	    for s in [
 51	        "",
 52	        "a",
 53	        "héllo",
 54	        "€uro",
 55	        "𐍈𐍈",
 56	        "\u{FFFE}\u{FDD0}",
 57	        "\u{10FFFF}a\u{7F}",
 58	    ] {
 59	        assert_eq!(char_count(s.as_bytes()), s.chars().count(), "{s:?}");
 60	        assert_eq!(valid_prefix_len(s.as_bytes()), s.len(), "{s:?}");
 61	    }
 62	}
 63	
 64	/// The prefix ends at the first byte that starts no sequence, or at the first sequence broken
 65	/// or cut short, and is every byte otherwise.
 66	#[test]
 67	fn valid_prefix_len_stops_at_the_first_broken_sequence() {
 68	    assert_eq!(valid_prefix_len(b""), 0);
 69	    assert_eq!(valid_prefix_len(b"abc"), 3);
 70	    assert_eq!(valid_prefix_len(b"\x80abc"), 0);
 71	    assert_eq!(valid_prefix_len(b"ab\xFFcd"), 2);
 72	    assert_eq!(valid_prefix_len(b"ab\xE2\x82"), 2);
 73	    assert_eq!(valid_prefix_len(b"ab\xE2\x82\xAC"), 5);
 74	    assert_eq!(valid_prefix_len(b"ab\xE2\x41\xAC"), 2);
 75	    assert_eq!(valid_prefix_len(b"\xC2\xA2\xC2"), 2);
 76	    // Structure alone: an overlong form and a surrogate are kept.
 77	    assert_eq!(valid_prefix_len(b"\xC0\x80\xED\xA0\x80"), 5);
 78	    // A hunk header cut inside its last character, as `git_xdiff_cb` sanitizes it.
 79	    let header = "@@ -1 +1 @@ fn café()".as_bytes();
 80	    let cut = &header[..header.len() - 3];
 81	    assert_eq!(valid_prefix_len(cut), cut.len() - 1);
 82	}
 83	
 84	/// The first and last code point of each sequence length decode, with their lengths; only
 85	/// the first sequence is read.
 86	#[test]
 87	fn decode_char_reads_each_length() {
 88	    assert_eq!(decode_char(b"\0"), Ok(('\0', 1)));
 89	    assert_eq!(decode_char(b"\x7F\xFF"), Ok(('\u{7F}', 1)));
 90	    assert_eq!(decode_char(b"\xC2\x80"), Ok(('\u{80}', 2)));
 91	    assert_eq!(decode_char(b"\xDF\xBF\xFF"), Ok(('\u{7FF}', 2)));
 92	    assert_eq!(decode_char(b"\xE0\xA0\x80"), Ok(('\u{800}', 3)));
 93	    assert_eq!(decode_char(b"\xEF\xBF\xBD"), Ok(('\u{FFFD}', 3)));
 94	    assert_eq!(decode_char(b"\xF0\x90\x80\x80"), Ok(('\u{10000}', 4)));
 95	    assert_eq!(decode_char(b"\xF4\x8F\xBF\xBD\x80"), Ok(('\u{10FFFD}', 4)));
 96	    assert_eq!(decode_char("¢$".as_bytes()), Ok(('¢', 2)));
 97	}
 98	
 99	/// Broken, cut short and overlong sequences, surrogates and code points past U+10FFFF are
100	/// refused.
101	#[test]
102	fn decode_char_refuses_malformed_sequences() {
103	    let refused: [&[u8]; 16] = [
104	        b"\x80",
105	        b"\xBF",
106	        b"\xF8\x80\x80\x80",
107	        b"\xFF",
108	        b"\xC2",
109	        b"\xE2\x82",
110	        b"\xF0\x90\x8D",
111	        b"\xC2\x41",
112	        b"\xE2\x82\x41",
113	        b"\xC0\x80",
114	        b"\xC1\xBF",
115	        b"\xE0\x9F\xBF",
116	        b"\xF0\x8F\xBF\xBF",
117	        b"\xED\xA0\x80",
118	        b"\xF4\x90\x80\x80",
119	        b"\xF7\xBF\xBF\xBF",
120	    ];
121	    for bytes in refused {
122	        assert_eq!(decode_char(bytes), Err(InvalidCodePoint), "{bytes:02X?}");
123	    }
124	    assert_eq!(decode_char(b"\xED\x9F\xBF"), Ok(('\u{D7FF}', 3)));
125	    assert_eq!(decode_char(b"\xEE\x80\x80"), Ok(('\u{E000}', 3)));
126	}
127	
128	/// The noncharacters are refused: U+FDD0 to U+FDEF, and the last two code points of every
129	/// plane. Their neighbours decode.
130	#[test]
131	fn decode_char_refuses_noncharacters() {
132	    let mut buf = [0; 4];
133	    for c in ('\u{FDD0}'..='\u{FDEF}').chain(
134	        (0..=0x10)
135	            .flat_map(|plane| [plane << 16 | 0xFFFE, plane << 16 | 0xFFFF])
136	            .filter_map(char::from_u32),
137	    ) {
138	        let bytes = c.encode_utf8(&mut buf).as_bytes();
139	        assert_eq!(decode_char(bytes), Err(InvalidCodePoint), "{c:?}");
140	    }
141	    for c in [
142	        '\u{FDCF}',
143	        '\u{FDF0}',
144	        '\u{FFFD}',
145	        '\u{1FFFD}',
146	        '\u{10FFFD}',
147	    ] {
148	        let bytes = c.encode_utf8(&mut buf).as_bytes();
149	        assert_eq!(decode_char(bytes), Ok((c, c.len_utf8())), "{c:?}");
150	    }
151	}
152	
153	/// Empty bytes hold no code point. `git_utf8_iterate(&out, str, 0)` reads `str` as if it were
154	/// unbounded, past the size its caller gives; the port refuses instead.
155	#[test]
156	fn decode_char_refuses_empty_bytes() {
157	    assert_eq!(decode_char(b""), Err(InvalidCodePoint));
158	}
159	
160	/// Every `char`'s encoding decodes to it, with its length, but for the noncharacters. Miri
161	/// samples them.
162	#[test]
163	fn decode_char_reads_every_char() {
164	    let step = if cfg!(miri) { 4099 } else { 1 };
165	    let mut buf = [0; 4];
166	    for c in (0..=0x10_FFFF).step_by(step).filter_map(char::from_u32) {
167	        let bytes = c.encode_utf8(&mut buf).as_bytes();
168	        let noncharacter =
169	            ('\u{FDD0}'..='\u{FDEF}').contains(&c) || u32::from(c) & 0xFFFF >= 0xFFFE;
170	        let expected = if noncharacter {
171	            Err(InvalidCodePoint)
172	        } else {
173	            Ok((c, c.len_utf8()))
174	        };
175	        assert_eq!(decode_char(bytes), expected, "{c:?}");
176	    }
177	}
178	
179	/// Decoding a string one code point at a time, as `next_hfs_char` does, reads every
180	/// character and ends at its end.
181	#[test]
182	fn decode_char_walks_a_string() {
183	    let s = "a\u{200C}é€𐍈.git";
184	    let mut rest = s.as_bytes();
185	    let mut chars = Vec::new();
186	    while !rest.is_empty() {
187	        let (c, len) = decode_char(rest).expect("valid");
188	        chars.push(c);
189	        rest = &rest[len..];
190	    }
191	    assert_eq!(chars, s.chars().collect::<Vec<_>>());
192	}
193	
194	/// The error is a `std::error::Error` with a message.
195	#[test]
196	fn invalid_code_point_is_an_error() {
197	    let error: Box<dyn std::error::Error> = Box::new(InvalidCodePoint);
198	    assert_eq!(error.to_string(), "invalid UTF-8 code point");
199	}

